import React from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";

import IncomeCategory from "./components/IncomeCategory";
import Questionnaire from "./components/Questionnaire";
import SpendingPriority from "./components/SpendingPriority";
import BudgetLimits from "./components/BudgetLimits";

function AppRouter({ setIncomeType }) {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<IncomeCategory onNext={setIncomeType} />} />
        <Route path="/questionnaire" element={<Questionnaire />} />
        <Route path="/spending" element={<SpendingPriority />} />
        <Route path="/budget" element={<BudgetLimits />} />
      </Routes>
    </BrowserRouter>
  );
}

export default AppRouter;
